sql.where:
dc.deleted_yn = 'N'

    AND dc.management_no ILIKE CONCAT('%', #{criteria.managementNo}, '%')


    AND personnel.name ILIKE CONCAT('%', #{criteria.teacherName}, '%')


    AND dc.certification_status = #{criteria.certificationStatus}


    AND dc.teacher_user_id = #{criteria.viewerUserId}


    AND EXISTS (
        SELECT 1
        FROM organization_user_mappings scope_mapping
        WHERE scope_mapping.user_id = #{criteria.viewerUserId}
          AND scope_mapping.organization_code = dc.organization_code
          AND scope_mapping.status = 'ACTIVE'
    )
